(* [comment removed for export] *)
Lemma read_walkB_err : forall (sp fd count e : Z) (ra gp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    F fc (m : mem) (lo : Z) junk junk1 (errv : word),
  stk asegs m lo (sp + -2144) -> 0x7fff7f800000 <= lo -> lo + 2304 <= sp -> sp < 2^47 -> 0 <= fd < 2^32 -> 0 <= count <= 65536 ->
  1 <= e <= 4095 ->
  rw_cells asegs m 0x63fda4 [C4 errv] ->
  rw_cells asegs m (sp + -2144) [CB 8 junk1; C8 (Z_to_bv 64 0x58728)] ->
  rw_cells asegs m (sp + -2128) [CB 2080 junk] ->
  rw_cells asegs m (sp + -48) [C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  mem_inv asegs m ->
  evt asegs (fun ms' => exists (m' : mem),
                 (exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word),
                 ms' = MS (mkR ra (Z_to_bv 64 sp) gp (Z_to_bv 64 0x63fe48) t0' t1' t2' s0 s1 (Z_to_bv 64 (-1)) a1' a2' a3' a4' a5' a6' a7'
                              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs))
                 /\ munch [(sp + -2144, sp); (0x63fda4, 0x63fda8)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
                 /\ rw_cells asegs m' 0x63fda4 [C4 (Z_to_bv 64 e)]
                 /\ stk asegs m' lo sp)
    (MS (mkR (Z_to_bv 64 0xf9574) (Z_to_bv 64 (sp + -2144)) gp (Z_to_bv 64 0x63fe48) t0 t1 t2 (Z_to_bv 64 sp) (Z_to_bv 64 g_read_stage)
             (Z_to_bv 64 (- e)) (Z_to_bv 64 g_read_stage) (Z_to_bv 64 count) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0)
             (Z_to_bv 64 0) (Z_to_bv 64 63) (Z_to_bv 64 count) (Z_to_bv 64 fd) (Z_to_bv 64 1) s5 s6 s7 s8 s9 s10 s11
             t3 t4 t5 t6)
